import { describe, it, expect } from "vitest";

// Store fixture mirrors the sibling unit suite's setup: an in-memory
// JSONL-backed session store whose home directory is pointed at a temp root.
const store = await import("../src/harness/jsonl-session-store.js");
const { readSessionTranscriptHistory } = await import(
  "../src/lib/session-transcript-history.js"
);

// Build the v1 history-sync "after" cursor that drives incremental
// pagination. The first non-incremental page exposes the session snapshot
// fields (generation/revision/eventCount) that every valid cursor must match.
function afterCursor(page, offset) {
  return Buffer.from(
    JSON.stringify({
      v: 1,
      view: "history-sync",
      sessionId: page.sessionId,
      generation: page.generation,
      revision: page.revision,
      eventCount: page.eventCount,
      offset,
    }),
  ).toString("base64url");
}

function start(id, turns = 4) {
  store.startSession(id, { provider: "test", model: "test" });
  for (let i = 0; i < turns; i++) {
    store.appendUserMessage(id, `question-${i}: ${"x".repeat(90)}`);
    store.appendAssistantMessage(id, `answer-${i}: ${"y".repeat(90)}`);
  }
}

describe("persistent body pagination boundaries (incremental after cursor)", () => {
  it("accepts the head boundary: offset 0 returns the first body row", () => {
    const id = "verify-07-head";
    start(id, 3); // 6 displayable rows
    const head = readSessionTranscriptHistory(id);
    expect(head.totalMessages).toBe(6);

    const page = readSessionTranscriptHistory(id, {
      limit: 2,
      cursor: afterCursor(head, 0),
    });
    // Head cursor is the accepted boundary: reading starts at the very first
    // displayable row, not after any prefix.
    expect(page.from).toBe(0);
    expect(page.messages.map((m) => m.ordinal)).toEqual([0, 1]);
    // With 6 rows and limit 2 the head page must still have a successor.
    expect(page.hasMore).toBe(true);
  });

  it("accepts the tail boundary: offset == count is an empty terminal page", () => {
    const id = "verify-07-tail";
    start(id, 3); // 6 displayable rows
    const head = readSessionTranscriptHistory(id);
    expect(head.totalMessages).toBe(6);

    const tail = readSessionTranscriptHistory(id, {
      limit: 2,
      cursor: afterCursor(head, 6),
    });
    // The final body has already been read; the boundary page stays empty and
    // never re-emits the last row (no duplicated boundary event).
    expect(tail.messages).toHaveLength(0);
    expect(tail.from).toBe(6);
    expect(tail.hasMore).toBe(false);
    // The successor cursor is stable at the same terminal offset.
    const again = readSessionTranscriptHistory(id, {
      limit: 2,
      cursor: tail.nextCursor,
    });
    expect(again.messages).toHaveLength(0);
    expect(again.hasMore).toBe(false);
  });

  it("rejects the first out-of-range value: negative offset throws", () => {
    const id = "verify-07-neg";
    start(id, 2); // 4 displayable rows
    const head = readSessionTranscriptHistory(id);

    expect(() =>
      readSessionTranscriptHistory(id, {
        limit: 2,
        cursor: afterCursor(head, -1),
      }),
    ).toThrow("invalid transcript history cursor");
  });

  it("iterating the tail cursor omits no body and duplicates no boundary row", () => {
    const id = "verify-07-iterate";
    start(id, 4); // 8 displayable rows
    const head = readSessionTranscriptHistory(id);
    expect(head.totalMessages).toBe(8);

    const seen = [];
    let cursor = afterCursor(head, 0);
    let page = readSessionTranscriptHistory(id, { limit: 3, cursor });
    let prevLast = -1;
    let pages = 0;
    do {
      // Each hasMore boundary hands off at exactly prevLast + 1, so consecutive
      // pages never overlap (no duplicated boundary row) nor skip a row.
      expect(page.from).toBe(prevLast + 1);
      expect(page.messages.length).toBeGreaterThan(0);
      expect(page.messages[0].ordinal).toBe(prevLast + 1);
      for (const row of page.messages) {
        // Strictly increasing and disjoint across every page boundary.
        expect(row.ordinal).toBeGreaterThan(prevLast);
        prevLast = row.ordinal;
        seen.push(row.ordinal);
      }
      pages += 1;
      cursor = page.nextCursor;
      page = readSessionTranscriptHistory(id, { limit: 3, cursor });
    } while (page.hasMore);

    // Every displayable body is returned exactly once, in order, with the final
    // body (ordinal count-1) present on the terminal page — never omitted.
    expect(seen).toEqual([0, 1, 2, 3, 4, 5, 6, 7]);
    expect(new Set(seen).size).toBe(8);
    // The terminal page still carries the final body and reports hasMore false.
    expect(page.messages.at(-1).ordinal).toBe(7);
    expect(page.hasMore).toBe(false);
    expect(pages).toBe(3);
  });
});

